1	import { env } from '../../lib/env.js';
2	import { META_GRAPH_VERSION } from '../../lib/meta-constants.js';
3	import type { AccessLevel, MetaAdAccount, MetaPage, MetaInstagramAccount, MetaProductCatalog, MetaAllAssets } from '@agency-platform/shared';
4	
5	/**
6	 * Meta (Facebook) OAuth Connector
7	 *
8	 * Handles OAuth 2.0 flow for Meta platforms (Facebook, Instagram, WhatsApp)
9	 *
10	 * Documentation: https://developers.facebook.com/docs/facebook-login/guides/advanced/manual-flow
11	 */
12	
13	interface MetaTokenResponse {
14	  access_token: string;
15	  token_type: string;
16	  expires_in?: number;
17	}
18	
19	interface MetaLongLivedTokenResponse {
20	  access_token: string;
21	  token_type: string;
22	  expires_in: number;
23	}
24	
25	interface MetaTokens {
26	  accessToken: string;
27	  tokenType: string;
28	  expiresIn?: number;
29	  expiresAt?: Date;
30	}
31	
32	interface MetaDebugTokenResponse {
33	  data?: {
34	    app_id?: string;
35	    type?: string;
36	    application?: string;
37	    data_access_expires_at?: number;
38	    expires_at?: number;
39	    is_valid?: boolean;
40	    scopes?: string[];
41	    user_id?: string;
42	  };
43	}
44	
45	export class MetaConnector {
46	  private readonly appId: string;
47	  private readonly appSecret: string;
48	  private readonly loginForBusinessConfigId?: string;
49	  private readonly redirectUri: string;
50	
51	  /**
52	   * Default Marketing API permissions for agency access
53	   *
54	   * These are NOT Facebook Login permissions (email, public_profile).
55	   * These are Marketing API permissions for ads and business management.
56	   *
57	   * Simplified to only request Business Manager access, not individual pages.
58	   *
59	   * Reference: https://developers.facebook.com/docs/marketing-api/overview
60	   */
61	  static readonly DEFAULT_SCOPES = [
62	    'ads_management',      // Create and manage ads
63	    'ads_read',            // Read ads data
64	    'business_management', // Access Business Manager assets (includes page management)
65	    // Note: pages_manage_metadata and pages_show_list are not valid OAuth scopes
66	    // They are automatically granted with business_management or configured at app level
67	  ];
68	
69	  constructor() {
70	    this.appId = env.META_APP_ID;
71	    this.appSecret = env.META_APP_SECRET;
72	    this.loginForBusinessConfigId = env.META_LOGIN_FOR_BUSINESS_CONFIG_ID;
73	    // Use agency-platforms callback for production (redirects to frontend)
74	    // For testing, use /api/oauth/meta/callback in Meta app settings
75	    this.redirectUri = `${env.API_URL}/agency-platforms/meta/callback`;
76	  }
77	
78	  /**
79	   * Generate OAuth authorization URL
80	   *
81	   * Uses Meta Marketing API permissions (NOT Facebook Login permissions).
82	   * Default scopes are for ads management, business management, and page access.
83	   *
84	   * @param state - CSRF protection token (should be stored in session/database)
85	   * @param scopes - Marketing API permissions to request
86	   * @param redirectUri - Optional override for redirect URI (used in client flow)
87	   * @returns Authorization URL to redirect user to
88	   */
89	  getAuthUrl(state: string, scopes?: string[], redirectUri?: string): string {
90	    const params = new URLSearchParams({
91	      client_id: this.appId,
92	      redirect_uri: redirectUri ?? this.redirectUri,
93	      state,
94	      response_type: 'code',
95	    });
96	
97	    // Agency Business Login uses config_id, but client invite OAuth must keep
98	    // requesting explicit scopes so non-role client users are not forced
99	    // through the agency Business Login configuration.
100	    if (this.loginForBusinessConfigId && !scopes) {
101	      params.set('config_id', this.loginForBusinessConfigId);
102	    } else {
103	      const scopesToUse = scopes ?? MetaConnector.DEFAULT_SCOPES;
104	      params.set('scope', scopesToUse.join(','));
105	    }
106	
107	    return `https://www.facebook.com/${META_GRAPH_VERSION}/dialog/oauth?${params.toString()}`;
108	  }
