110	  /**
111	   * Exchange authorization code for short-lived access token
112	   *
113	   * @param code - Authorization code from OAuth callback
114	   * @param redirectUri - Optional override for redirect URI (must match getAuthUrl)
115	   * @returns Short-lived access token (expires in ~2 hours)
116	   */
117	  async exchangeCode(code: string, redirectUri?: string): Promise<MetaTokens> {
118	    const params = new URLSearchParams({
119	      client_id: this.appId,
120	      client_secret: this.appSecret,
121	      redirect_uri: redirectUri ?? this.redirectUri,
122	      code,
123	    });
124	
125	    const response = await fetch(
126	      `https://graph.facebook.com/${META_GRAPH_VERSION}/oauth/access_token?${params.toString()}`,
127	      { method: 'GET' }
128	    );
129	
130	    if (!response.ok) {
131	      const error = await response.text();
132	      throw new Error(`Meta token exchange failed: ${error}`);
133	    }
134	
135	    const data = (await response.json()) as MetaTokenResponse;
136	
137	    return {
138	      accessToken: data.access_token,
139	      tokenType: data.token_type,
140	      expiresIn: data.expires_in,
141	      expiresAt: data.expires_in
142	        ? new Date(Date.now() + data.expires_in * 1000)
143	        : undefined,
144	    };
145	  }
