147	  /**
148	   * Exchange short-lived token for long-lived token
149	   *
150	   * Meta best practice: Always exchange for long-lived tokens (60 days)
151	   *
152	   * @param shortLivedToken - Short-lived access token from exchangeCode
153	   * @returns Long-lived access token (expires in ~60 days)
154	   */
155	  async getLongLivedToken(shortLivedToken: string): Promise<MetaTokens> {
156	    const params = new URLSearchParams({
157	      grant_type: 'fb_exchange_token',
158	      client_id: this.appId,
159	      client_secret: this.appSecret,
160	      fb_exchange_token: shortLivedToken,
161	    });
162	
163	    const response = await fetch(
164	      `https://graph.facebook.com/${META_GRAPH_VERSION}/oauth/access_token?${params.toString()}`,
165	      { method: 'GET' }
166	    );
167	
168	    if (!response.ok) {
169	      const error = await response.text();
170	      throw new Error(`Meta long-lived token exchange failed: ${error}`);
171	    }
172	
173	    const data = (await response.json()) as MetaLongLivedTokenResponse;
174	
175	    return {
176	      accessToken: data.access_token,
177	      tokenType: data.token_type,
178	      expiresIn: data.expires_in,
179	      expiresAt: new Date(Date.now() + data.expires_in * 1000),
180	    };
181	  }
