183	  /**
184	   * Refresh access token (NOT SUPPORTED BY META)
185	   *
186	   * Meta does not support token refresh via refresh_token.
187	   * Instead, Meta uses long-lived tokens valid for 60 days.
188	   * When tokens expire, the user must re-authorize via OAuth flow.
189	   *
190	   * For token refresh, use the token refresh job to detect expiring tokens
191	   * and prompt users to re-authorize before expiration.
192	   *
193	   * @throws Error - Always throws as this is not supported
194	   */
195	  async refreshToken(_refreshToken: string): Promise<MetaTokens> {
196	    throw new Error(
197	      'Meta does not support token refresh via refresh_token. ' +
198	      'Meta uses long-lived tokens valid for 60 days. ' +
199	      'When tokens expire, the user must re-authorize via OAuth flow. ' +
200	      'Use getLongLivedToken() during initial authorization to get 60-day tokens.'
201	    );
202	  }
