307	  /**
308	   * Get all Meta Business Manager accounts for the agency
309	   *
310	   * Fetches all Business Manager accounts the agency has access to.
311	   * This is used to display available businesses in the UI after connection.
312	   *
313	   * @param accessToken - Valid Meta access token
314	   * @returns Business Manager accounts with metadata
315	   */
316	  async getBusinessAccounts(accessToken: string): Promise<{
317	    businesses: Array<{
318	      id: string;
319	      name: string;
320	      verticalName?: string;
321	      verificationStatus?: string;
322	    }>;
323	    hasAccess: boolean;
324	  }> {
325	    const businesses: Array<{
326	      id: string;
327	      name: string;
328	      verticalName?: string;
329	      verificationStatus?: string;
330	    }> = [];
331	
332	    const seenBusinessIds = new Set<string>();
333	    const recordBusiness = (business: {
334	      id?: string;
335	      name?: string;
336	      vertical_name?: string;
337	      verification_status?: string;
338	    }): boolean => {
339	      if (!business.id || !business.name || seenBusinessIds.has(business.id)) {
340	        return false;
341	      }
342	
343	      seenBusinessIds.add(business.id);
344	      businesses.push({
345	        id: business.id,
346	        name: business.name,
347	        verticalName: business.vertical_name,
348	        verificationStatus: business.verification_status,
349	      });
350	      return true;
351	    };
352	
353	    const withAccessToken = (url: string): string => {
354	      const parsedUrl = new URL(url);
355	      if (!parsedUrl.searchParams.has('access_token')) {
356	        parsedUrl.searchParams.set('access_token', accessToken);
357	      }
358	      return parsedUrl.toString();
359	    };
360	
361	    const fetchBusinessCollection = async (
362	      url: string,
363	      extractBusinesses: (payload: any) => Array<{
364	        id?: string;
365	        name?: string;
366	        vertical_name?: string;
367	        verification_status?: string;
368	      }>
369	    ): Promise<string[]> => {
370	      let nextUrl: string | null = withAccessToken(url);
371	      const discoveredBusinessIds: string[] = [];
372	
373	      while (nextUrl) {
374	        const response = await fetch(nextUrl, { method: 'GET' });
375	
376	        if (!response.ok) {
377	          const error = await response.text();
378	          throw new Error(`Failed to fetch business accounts: ${error}`);
379	        }
380	
381	        const data = await response.json() as {
382	          data?: unknown[];
383	          paging?: {
384	            next?: string;
385	          };
386	        };
387	
388	        for (const business of extractBusinesses(data)) {
389	          if (recordBusiness(business) && business.id) {
390	            discoveredBusinessIds.push(business.id);
391	          }
392	        }
393	
394	        nextUrl = data.paging?.next ? withAccessToken(data.paging.next) : null;
395	      }
396	
397	      return discoveredBusinessIds;
398	    };
399	
400	    const queuedBusinessIds = await fetchBusinessCollection(
401	      `https://graph.facebook.com/${META_GRAPH_VERSION}/me/businesses?fields=id,name,vertical_name,verification_status`,
402	      (payload) => (payload.data || []) as Array<{
403	        id: string;
404	        name: string;
405	        vertical_name?: string;
406	        verification_status?: string;
407	      }>
408	    );
409	
410	    try {
411	      const businessUserBusinessIds = await fetchBusinessCollection(
412	        `https://graph.facebook.com/${META_GRAPH_VERSION}/me/business_users?fields=business{id,name,verification_status}`,
413	        (payload) =>
414	          ((payload.data || []) as Array<{
415	            business?: {
416	              id?: string;
417	              name?: string;
418	              vertical_name?: string;
419	              verification_status?: string;
420	            };
421	          }>)
422	            .map((entry) => entry.business)
423	            .filter((business): business is {
424	              id?: string;
425	              name?: string;
426	              vertical_name?: string;
427	              verification_status?: string;
428	            } => Boolean(business))
429	      );
430	
431	      queuedBusinessIds.push(...businessUserBusinessIds);
432	    } catch (error) {
433	      console.warn('Failed to fetch supplemental Meta business_users data; continuing with primary businesses list.', error);
434	    }
435	
436	    // OBO and partner setups can expose additional client portfolios under managed_businesses.
437	    const pendingBusinessIds = [...queuedBusinessIds];
438	    const traversedBusinessIds = new Set<string>();
439	
440	    while (pendingBusinessIds.length > 0) {
441	      const currentBusinessId = pendingBusinessIds.shift();
442	      if (!currentBusinessId || traversedBusinessIds.has(currentBusinessId)) {
443	        continue;
444	      }
445	
446	      traversedBusinessIds.add(currentBusinessId);
447	
448	      try {
449	        const managedBusinessIds = await fetchBusinessCollection(
450	          `https://graph.facebook.com/${META_GRAPH_VERSION}/${currentBusinessId}/managed_businesses?fields=id,name,vertical_name,verification_status`,
451	          (payload) => (payload.data || []) as Array<{
452	            id: string;
453	            name: string;
454	            vertical_name?: string;
455	            verification_status?: string;
456	          }>
457	        );
458	
459	        pendingBusinessIds.push(...managedBusinessIds);
460	      } catch (error) {
461	        console.warn(
462	          `Failed to fetch managed businesses for ${currentBusinessId}; continuing with directly accessible businesses only.`,
463	          error
464	        );
465	      }
466	    }
467	
468	    return {
469	      businesses,
470	      hasAccess: businesses.length > 0,
471	    };
472	  }
