629	  /**
630	   * Verify agency has access to client's Meta assets
631	   *
632	   * Uses agency's OAuth token to query Meta Business Manager API for granted partnerships.
633	   *
634	   * @param agencyAccessToken - Agency's OAuth access token
635	   * @param businessId - Agency's Business Manager ID
636	   * @param clientEmail - Client's email (for validation)
637	   * @param requiredAccessLevel - Minimum access level required
638	   * @returns Verification result with granted access details
639	   */
640	  async verifyClientAccess(
641	    agencyAccessToken: string,
642	    businessId: string,
643	    clientEmail: string,
644	    requiredAccessLevel: AccessLevel
645	  ): Promise<{
646	    hasAccess: boolean;
647	    accessLevel: AccessLevel;
648	    businessName?: string;
649	    assets: Array<{
650	      type: 'ad_account' | 'page' | 'instagram_account';
651	      id: string;
652	      name: string;
653	      permissions: string[];
654	    }>;
655	    error?: string;
656	  }> {
657	    try {
658	      // Query the agency's Business Manager to check partnerships
659	      // This returns all businesses the agency manages
660	      const businessResponse = await fetch(
661	        `https://graph.facebook.com/${META_GRAPH_VERSION}/${businessId}?fields=name,id&access_token=${agencyAccessToken}`,
662	        { method: 'GET' }
663	      );
664	
665	      if (!businessResponse.ok) {
666	        return {
667	          hasAccess: false,
668	          accessLevel: 'read_only',
669	          assets: [],
670	          error: 'Failed to verify Business Manager access',
671	        };
672	      }
673	
674	      const businessData = await businessResponse.json() as {
675	        name?: string;
676	        id?: string;
677	      };
678	
679	      // For MVP, we consider access granted if the Business Manager exists and token is valid
680	      // In production, you would query specific client relationships
681	      // This could be done via:
682	      // 1. Querying client's business settings for partner relationships
683	      // 2. Checking granted ad accounts and permissions
684	      // 3. Verifying specific access levels match requirements
685	
686	      // Map access levels to Meta permissions
687	      const accessLevelMapping: Record<AccessLevel, string[]> = {
688	        admin: ['ADVERTISE', 'MANAGE', 'ANALYZE'],
689	        standard: ['ADVERTISE', 'ANALYZE'],
690	        read_only: ['ANALYZE'],
691	        email_only: [],
692	      };
693	
694	      // For MVP, return basic verification
695	      // In production, query the client's business to find this agency as a partner
696	      const hasAccess = businessData.id === businessId;
697	
698	      return {
699	        hasAccess,
700	        accessLevel: hasAccess ? requiredAccessLevel : 'read_only',
701	        businessName: businessData.name,
702	        assets: [],
703	      };
704	    } catch (error) {
705	      return {
706	        hasAccess: false,
707	        accessLevel: 'read_only',
708	        assets: [],
709	        error: error instanceof Error ? error.message : 'Unknown error',
710	      };
711	    }
712	  }
