      return sendError(reply, 'ACCESS_REQUEST_NOT_FOUND', 'Access request not found', 404);
    }

    const timezones = metaAssetCreationService.getSupportedTimezones();

    return reply.send({
      data: { timezones },
      error: null,
    });
  });
}

