250	// Bounded fan-out, order preserved: each result lands at its input index.
251	async function mapInChunks<T, R>(items: T[], mapper: (item: T) => Promise<R>): Promise<R[]> {
252	  const results = new Array<R>(items.length);
253	  for (let start = 0; start < items.length; start += ASSET_OPERATION_CONCURRENCY) {
