67	    selectedBusinessId?: string;
68	    selectedBusinessName?: string;
69	    businesses?: Array<{ id: string; name: string }>;
70	    selectionRequired?: boolean;
71	    // Extended properties for grant step
72	    selectedPagesWithNames?: Array<{ id: string; name: string }>;
73	    selectedAdAccountsWithNames?: Array<{ id: string; name: string }>;
74	    selectedInstagramWithNames?: Array<{ id: string; name: string }>;
75	    selectedAssetNames?: string[];
76	    allPages?: MetaAssets['pages'];
77	    allAdAccounts?: MetaAssets['adAccounts'];
78	    allInstagramAccounts?: MetaAssets['instagramAccounts'];
79	  }) => void;
80	  onError?: (error: string) => void;
81	}
82	
83	export function MetaAssetSelector({
84	  sessionId,
85	  accessRequestToken,
86	  businessId,
87	  allowedAssetTypes = ['ad_account', 'page', 'instagram'],
88	  onSelectionChange,
89	  onError,
90	}: MetaAssetSelectorProps) {
91	  const [isLoading, setIsLoading] = useState(true);
92	  const [assets, setAssets] = useState<MetaAssets | null>(null);
93	  const [error, setError] = useState<string | null>(null);
94	  const [selectedBusinessId, setSelectedBusinessId] = useState<string | null>(null);
95	  const [selectedBusinessName, setSelectedBusinessName] = useState<string | null>(null);
96	  const [pendingBusinessId, setPendingBusinessId] = useState('');
97	
98	  // Selection state
99	  const [selectedAdAccounts, setSelectedAdAccounts] = useState<Set<string>>(new Set());
100	  const [selectedPages, setSelectedPages] = useState<Set<string>>(new Set());
101	  const [selectedInstagram, setSelectedInstagram] = useState<Set<string>>(new Set());
102	
103	  // Creation UI state
104	  const [showAdAccountCreator, setShowAdAccountCreator] = useState(false);
105	  const [showPageCreator, setShowPageCreator] = useState(false);
106	
107	  // Track if we've already captured the event (to avoid duplicates)
108	  const hasTrackedSelection = useRef(false);
109	  const activeBusinessId = selectedBusinessId || businessId || undefined;
110	  const showAdAccounts = allowedAssetTypes.includes('ad_account');
111	  const showPages = allowedAssetTypes.includes('page');
112	  const showInstagramAccounts = allowedAssetTypes.includes('instagram');
113	
114	  const assetTypeLabel = [
115	    showAdAccounts ? 'ad accounts' : null,
116	    showPages ? 'pages' : null,
117	    showInstagramAccounts ? 'Instagram accounts' : null,
118	  ]
119	    .filter(Boolean)
120	    .join(', ');
121	
122	  // Handle successful ad account creation - auto-select and refresh
123	  const handleAdAccountCreated = (newAccount: { id: string; name: string }) => {
124	    // Refresh assets to get the updated list
125	    fetchAssets(activeBusinessId).then(() => {
126	      // Auto-select the newly created account
127	      setSelectedAdAccounts((prev) => new Set([...prev, newAccount.id]));
128	      setShowAdAccountCreator(false);
129	    });
130	  };
131	
132	  // Handle page creation - refresh list
133	  const handlePageCreated = () => {
134	    fetchAssets(activeBusinessId).then(() => {
135	      setShowPageCreator(false);
136	    });
137	  };
138	  const fetchAssets = async (requestedBusinessId?: string) => {
139	    try {
140	      setIsLoading(true);
141	      setError(null);
142	
143	      const apiUrl = getApiBaseUrl();
144	      const query = new URLSearchParams({
145	        connectionId: sessionId,
146	      });
147	
148	      if (requestedBusinessId) {
149	        query.set('businessId', requestedBusinessId);
150	      }
151	
152	      const response = await fetch(
153	        `${apiUrl}/api/client/${accessRequestToken}/assets/meta_ads?${query.toString()}`
154	      );
155	      const json = await parseJsonResponse<{ data?: MetaAssets; error?: { message?: string } }>(
156	        response,
157	        {
158	          fallbackErrorMessage: 'Failed to load accounts',
159	        }
160	      );
161	
162	      if (json.error) {
163	        throw new Error(json.error.message || 'Failed to load accounts');
164	      }
165	
166	      const fetchedAssets = json.data || { adAccounts: [], pages: [], instagramAccounts: [] };
167	      setAssets(fetchedAssets);
168	      setSelectedBusinessId(fetchedAssets.selectedBusinessId || requestedBusinessId || null);
169	      setSelectedBusinessName(fetchedAssets.selectedBusinessName || null);
170	      setPendingBusinessId(fetchedAssets.selectedBusinessId || requestedBusinessId || '');
171	    } catch (err) {
172	      const errorMessage = err instanceof Error ? err.message : 'Failed to load accounts';
173	      setError(errorMessage);
174	      onError?.(errorMessage);
175	    } finally {
176	      setIsLoading(false);
177	    }
178	  };
179	
180	  // Fetch assets on mount
181	  useEffect(() => {
182	    if (sessionId) {
183	      fetchAssets(selectedBusinessId || undefined);
184	    }
185	    // eslint-disable-next-line react-hooks/exhaustive-deps
186	  }, [sessionId, accessRequestToken]);
187	
188	  // Notify parent of changes
189	  useEffect(() => {
190	    // Include full asset objects for grant step
191	    const selectedPagesWithNames = Array.from(selectedPages).map((id) => {
192	      const page = assets?.pages.find((p) => p.id === id);
193	      return page ? { id: page.id, name: page.name } : { id, name: id };
194	    });
195	    
196	    const selectedAdAccountsWithNames = Array.from(selectedAdAccounts).map((id) => {
197	      const account = assets?.adAccounts.find((a) => a.id === id);
198	      return account ? { id: account.id, name: account.name } : { id, name: id };
199	    });
200	    
201	    const selectedInstagramWithNames = Array.from(selectedInstagram).map((id) => {
202	      const account = assets?.instagramAccounts.find((a) => a.id === id);
203	      return account ? { id: account.id, name: account.username || account.name || id } : { id, name: id };
204	    });
205	
206	    // Track meta_assets_selected when selection changes (debounced)
207	    const totalSelected =
208	      (showAdAccounts ? selectedAdAccounts.size : 0) +
209	      (showPages ? selectedPages.size : 0) +
210	      (showInstagramAccounts ? selectedInstagram.size : 0);
211	    let selectionTrackingTimeoutId: ReturnType<typeof setTimeout> | null = null;
212	
213	    if (totalSelected > 0 && !hasTrackedSelection.current) {
214	      // Debounce the tracking to avoid spamming events
215	      selectionTrackingTimeoutId = setTimeout(() => {
216	        posthog.capture('meta_assets_selected', {
217	          session_id: sessionId,
218	          ad_accounts_selected: selectedAdAccounts.size,
219	          pages_selected: selectedPages.size,
220	          instagram_accounts_selected: selectedInstagram.size,
221	          total_selected: totalSelected,
222	          available_ad_accounts: assets?.adAccounts?.length || 0,
223	          available_pages: assets?.pages?.length || 0,
224	          available_instagram: assets?.instagramAccounts?.length || 0,
225	        });
226	        hasTrackedSelection.current = true;
227	      }, 2000); // Wait 2 seconds after last selection change
228	    }
229	
230	    // Build flat list of selected asset names for Step 3 summary
231	    const selectedAssetNames = [
232	      ...(showAdAccounts ? selectedAdAccountsWithNames.map((a) => a.name) : []),
233	      ...(showPages ? selectedPagesWithNames.map((p) => p.name) : []),
234	      ...(showInstagramAccounts ? selectedInstagramWithNames.map((ig) => ig.name) : []),
235	    ];
236	
237	    onSelectionChange({
238	      adAccounts: Array.from(selectedAdAccounts),
239	      pages: Array.from(selectedPages),
240	      instagramAccounts: Array.from(selectedInstagram),
241	      selectedBusinessId: selectedBusinessId || undefined,
242	      selectedBusinessName: selectedBusinessName || undefined,
243	      businesses: assets?.businesses || [],
244	      selectionRequired: assets?.selectionRequired,
245	      // Include full objects for grant step
246	      selectedPagesWithNames,
247	      selectedAdAccountsWithNames,
248	      selectedInstagramWithNames,
249	      selectedAssetNames,
250	      // Store all assets for lookup
251	      allPages: assets?.pages || [],
252	      allAdAccounts: assets?.adAccounts || [],
253	      allInstagramAccounts: assets?.instagramAccounts || [],
254	    });
255	
256	    return () => {
257	      if (selectionTrackingTimeoutId) {
258	        clearTimeout(selectionTrackingTimeoutId);
259	      }
260	    };
261	    // eslint-disable-next-line react-hooks/exhaustive-deps
262	  }, [selectedAdAccounts, selectedPages, selectedInstagram, assets]);
263	
264	  // Loading state
265	  if (isLoading) {
266	    return (
267	      <AssetSelectorLoading
268	        message={`Finding your ${assetTypeLabel || 'accounts'}...`}
269	      />
270	    );
271	  }
272	
273	  // Error state
274	  if (error) {
275	    return (
276	      <AssetSelectorError
277	        title="Couldn't load Meta accounts"
278	        message={error}
279	        onRetry={fetchAssets}
280	      />
281	    );
282	  }
283	
284	  // Convert assets to Asset format (for Instagram) and MultiSelectOption format (for Ad Accounts and Pages)
285	  const adAccountAssets = (assets?.adAccounts || []).map((account) => ({
286	    id: account.id,
287	    name: account.name,
288	    description: account.status || account.currency || '',
289	  }));
290	
291	  const pageAssets = (assets?.pages || []).map((page) => ({
292	    id: page.id,
293	    name: page.name,
294	    description: page.category || '',
295	  }));
296	
297	  const instagramAssets: Asset[] = (assets?.instagramAccounts || []).map((account) => ({
298	    id: account.id,
299	    name: account.username || account.name || account.id,
300	    metadata: {
301	      id: account.id,
302	      avatar: account.avatar,
303	    },
304	  }));
305	
306	  const totalSelected =
307	    (showAdAccounts ? selectedAdAccounts.size : 0) +
308	    (showPages ? selectedPages.size : 0) +
309	    (showInstagramAccounts ? selectedInstagram.size : 0);
310	  const availableBusinesses = assets?.businesses || [];
311	  const requiresBusinessSelection = Boolean(
312	    assets?.selectionRequired && !selectedBusinessId && availableBusinesses.length > 0
313	  );
314	  const creationBusinessId = selectedBusinessId || businessId;
315	
316	  const handleBusinessSelectionLoad = () => {
317	    if (!pendingBusinessId) return;
318	    setSelectedAdAccounts(new Set());
319	    setSelectedPages(new Set());
320	    setSelectedInstagram(new Set());
321	    void fetchAssets(pendingBusinessId);
322	  };
323	
324	  const handleSwitchBusiness = () => {
325	    setSelectedBusinessId(null);
326	    setSelectedBusinessName(null);
327	    setPendingBusinessId('');
328	    setSelectedAdAccounts(new Set());
329	    setSelectedPages(new Set());
330	    setSelectedInstagram(new Set());
331	    setShowAdAccountCreator(false);
332	    setShowPageCreator(false);
333	    setAssets((currentAssets) =>
334	      currentAssets
335	        ? {
336	            ...currentAssets,
337	            selectedBusinessId: null,
338	            selectedBusinessName: null,
339	            selectionRequired: true,
340	            adAccounts: [],
341	            pages: [],
342	            instagramAccounts: [],
343	          }
344	        : currentAssets
345	    );
346	  };
347	
348	  return (
349	    <div className="space-y-6">
350	      {requiresBusinessSelection ? (
351	        <div className="border-2 border-black dark:border-white bg-[rgb(var(--warm-gray))]/20 p-6 space-y-4">
352	          <div>
353	            <h3 className="text-lg font-bold text-[rgb(var(--ink))] font-display">
354	              Select Business Portfolio
355	            </h3>
356	            <p className="text-sm text-[rgb(var(--muted-foreground))] mt-1">
357	              Choose the client Business Portfolio that owns the Meta assets you want to share.
358	            </p>
359	          </div>
360	
361	          <div className="space-y-3">
362	            <label
363	              htmlFor="meta-business-portfolio"
364	              className="block text-xs font-bold uppercase tracking-[0.18em] text-[rgb(var(--muted-foreground))]"
365	            >
366	              Business Portfolio
367	            </label>
368	            <SingleSelect
369	              options={availableBusinesses.map((b) => ({
370	                value: b.id,
371	                label: `${b.name} (${b.id})`,
372	              }))}
373	              value={pendingBusinessId}
374	              onChange={(v) => setPendingBusinessId(v)}
375	              placeholder="Select a portfolio..."
376	              ariaLabel="Business Portfolio"
377	              triggerClassName="border-2 border-black dark:border-white min-h-[48px]"
378	            />
379	            <button
380	              type="button"
381	              onClick={handleBusinessSelectionLoad}
382	              disabled={!pendingBusinessId || isLoading}
383	              className="inline-flex min-h-[48px] items-center justify-center bg-[rgb(var(--ink))] px-5 py-3 font-bold text-white disabled:cursor-not-allowed disabled:bg-[rgb(var(--muted))]/40 disabled:text-[rgb(var(--muted-foreground))]"
384	            >
385	              Load accounts
386	            </button>
387	          </div>
388	        </div>
389	      ) : null}
390	
391	      {selectedBusinessName ? (
392	        <div className="border-2 border-black dark:border-white bg-[rgb(var(--card))] px-4 py-3">
393	          <div className="flex items-center justify-between gap-4">
394	            <div>
395	              <p className="text-sm font-bold text-[rgb(var(--ink))]">
396	                Sharing from {selectedBusinessName}
397	              </p>
398	              {availableBusinesses.length > 1 ? (
399	                <p className="text-xs text-[rgb(var(--muted-foreground))] mt-1">
400	                  Switch to another client Business Portfolio before continuing if these assets are not the right ones.
401	                </p>
402	              ) : null}
403	            </div>
404	            {availableBusinesses.length > 1 ? (
405	              <button
406	                type="button"
407	                onClick={handleSwitchBusiness}
408	                className="inline-flex min-h-[44px] items-center justify-center border-2 border-black dark:border-white bg-[rgb(var(--paper))] px-4 py-2 text-sm font-bold text-[rgb(var(--ink))] hover:bg-[rgb(var(--muted))]/20"
409	              >
410	                Switch business
411	              </button>
412	            ) : null}
413	          </div>
414	        </div>
415	      ) : null}
416	
417	      {requiresBusinessSelection ? null : (
418	        <>
419	      {/* Asset Groups */}
420	      <div className="space-y-4">
421	        {/* Ad Accounts - Multi-select Combobox or Creator */}
422	        {showAdAccounts ? (
423	        <div>
424	          <div className="flex items-center gap-3 mb-3">
425	            <div className="w-10 h-10 border-2 border-black dark:border-white bg-[rgb(var(--coral))] flex items-center justify-center">
426	              <span className="text-white text-lg">💼</span>
427	            </div>
428	            <div>
429	              <h3 className="text-lg font-bold text-[rgb(var(--ink))] font-display">Ad Accounts</h3>
430	              <p className="text-sm text-[rgb(var(--muted-foreground))] mt-0.5">
431	                {selectedAdAccounts.size} of {adAccountAssets.length} selected
432	              </p>
433	            </div>
434	          </div>
435	
436	          {/* Show creator if empty and user clicked "Create New" */}
437	          {showAdAccountCreator && creationBusinessId ? (
438	            <div className="border-2 border-[rgb(var(--coral))] bg-[rgb(var(--coral))]/5 p-4 rounded-lg mb-3">
439	              <div className="flex items-center justify-between mb-3">
440	                <h4 className="font-bold text-[rgb(var(--ink))]">Create New Ad Account</h4>
441	                <button
442	                  onClick={() => setShowAdAccountCreator(false)}
443	                  className="text-sm text-[rgb(var(--muted-foreground))] hover:text-[rgb(var(--coral))] underline"
444	                >
445	                  Cancel
446	                </button>
447	              </div>
448	              <MetaAssetCreator
449	                connectionId={sessionId}
450	                businessId={creationBusinessId}
451	                accessRequestToken={accessRequestToken}
452	                onSuccess={handleAdAccountCreated}
453	                onError={onError}
454	              />
455	            </div>
456	          ) : adAccountAssets.length > 0 ? (
457	            <MultiSelectCombobox
458	              options={adAccountAssets.map((asset) => ({
459	                id: asset.id,
460	                name: asset.name,
461	                description: asset.description,
462	              }))}
463	              selectedIds={selectedAdAccounts}
464	              onSelectionChange={setSelectedAdAccounts}
465	              placeholder="Select ad accounts..."
466	            />
467	          ) : (
468	            /* Empty state with create option */
469	            <div className="py-8 text-center px-6">
470	              {/* Empty state icon - Brutalist Square */}
471	              <div className="w-20 h-20 border-2 border-black dark:border-white bg-[rgb(var(--muted))]/30 dark:bg-[rgb(var(--muted))]/60 flex items-center justify-center mx-auto mb-4">
472	                <span className="text-4xl" role="img" aria-label="Empty">
473	                  📭
474	                </span>
475	              </div>
476	
477	              {/* Message */}
478	              <h3 className="text-lg font-bold text-[rgb(var(--ink))] mb-2 font-display">No Ad Accounts Found</h3>
479	              <p className="text-sm text-[rgb(var(--muted-foreground))] mb-4 max-w-sm mx-auto">
480	                You don't have any ad accounts in this Business Manager yet. Create one to get started.
481	              </p>
482	
483	              {/* Create button */}
484	              {creationBusinessId ? (
485	                <button
486	                  onClick={() => setShowAdAccountCreator(true)}
487	                  className="inline-flex items-center justify-center gap-2 px-6 py-3 bg-[rgb(var(--coral))] text-white border-2 border-black dark:border-white rounded-[0.75rem] font-bold uppercase tracking-wide shadow-brutalist hover:shadow-none hover:translate-x-[2px] hover:translate-y-[2px] transition-all min-h-[48px]"
488	                >
489	                  <Plus className="w-5 h-5" />
490	                  Create Ad Account
491	                </button>
492	              ) : (
493	                <div className="border-2 border-[rgb(var(--warning))] bg-[rgb(var(--warning))]/10 p-4 text-sm text-[rgb(var(--warning))] max-w-sm mx-auto">
494	                  Select a Business Portfolio before creating ad accounts.
495	                </div>
496	              )}
497	            </div>
498	          )}
499	        </div>
500	        ) : null}
501	
502	        {/* Pages - Multi-select Combobox or Guided Redirect */}
503	        {showPages ? (
504	        <div>
505	          <div className="flex items-center gap-3 mb-3">
506	            <div className="w-10 h-10 border-2 border-black dark:border-white bg-[rgb(var(--coral))]/100 flex items-center justify-center">
507	              <span className="text-white text-lg">📄</span>
508	            </div>
509	            <div>
510	              <h3 className="text-lg font-bold text-[rgb(var(--ink))] font-display">Pages</h3>
511	              <p className="text-sm text-[rgb(var(--muted-foreground))] mt-0.5">
512	                {selectedPages.size} of {pageAssets.length} selected
513	              </p>
514	            </div>
515	          </div>
516	
517	          {/* Show guided redirect if empty */}
518	          {pageAssets.length > 0 ? (
519	            <MultiSelectCombobox
520	              options={pageAssets.map((asset) => ({
521	                id: asset.id,
522	                name: asset.name,
523	                description: asset.description,
524	              }))}
525	              selectedIds={selectedPages}
526	              onSelectionChange={setSelectedPages}
527	              placeholder="Select pages..."
528	            />
529	          ) : showPageCreator ? (
530	            /* Guided redirect card */
531	            <GuidedRedirectCard
532	              title="Create a Facebook Page"
533	              description="Pages must be created in Meta Business Manager. Follow these steps:"
534	              businessManagerUrl={`https://business.facebook.com/settings/${creationBusinessId}/pages`}
535	              instructions={[
536	                { title: 'Click the button below to open Meta Business Manager', description: 'A new tab will open' },
537	                { title: 'Click "Add a Page" or "Create a New Page"', description: 'Choose to create a new page or add an existing one' },
538	                { title: 'Follow the prompts to set up your page', description: 'Add name, category, and description' },
539	                { title: 'Return here and click "Refresh List"', description: 'Your new page will appear in the list' },
540	              ]}
541	              onRefresh={handlePageCreated}
542	            />
543	          ) : (
544	            /* Empty state with create option */
545	            <div className="py-8 text-center px-6">
546	              {/* Empty state icon - Brutalist Square */}
547	              <div className="w-20 h-20 border-2 border-black dark:border-white bg-[rgb(var(--muted))]/30 dark:bg-[rgb(var(--muted))]/60 flex items-center justify-center mx-auto mb-4">
548	                <span className="text-4xl" role="img" aria-label="Empty">
549	                  📄
550	                </span>
551	              </div>
552	
553	              {/* Message */}
554	              <h3 className="text-lg font-bold text-[rgb(var(--ink))] mb-2 font-display">No Pages Found</h3>
555	              <p className="text-sm text-[rgb(var(--muted-foreground))] mb-4 max-w-sm mx-auto">
556	                You don't have any Facebook Pages in this Business Manager. Create one to get started.
557	              </p>
558	
559	              {/* Create button */}
560	              {creationBusinessId ? (
561	                <button
562	                  onClick={() => setShowPageCreator(true)}
563	                  className="inline-flex items-center justify-center gap-2 px-6 py-3 bg-[rgb(var(--coral))] text-white border-2 border-black dark:border-white rounded-[0.75rem] font-bold uppercase tracking-wide shadow-brutalist hover:shadow-none hover:translate-x-[2px] hover:translate-y-[2px] transition-all min-h-[48px]"
564	                >
565	                  <Plus className="w-5 h-5" />
566	                  Create Page
567	                </button>
568	              ) : (
569	                <div className="border-2 border-[rgb(var(--warning))] bg-[rgb(var(--warning))]/10 p-4 text-sm text-[rgb(var(--warning))] max-w-sm mx-auto">
570	                  Select a Business Portfolio before creating pages.
571	                </div>
572	              )}
573	            </div>
574	          )}
575	        </div>
576	        ) : null}
577	
578	        {/* Instagram Accounts - Keep as AssetGroup for now */}
579	        {showInstagramAccounts ? (
580	        <AssetGroup
581	          title="Instagram Accounts"
582	          assets={instagramAssets}
583	          selectedIds={selectedInstagram}
584	          onSelectionChange={setSelectedInstagram}
585	          icon={
586	            <div className="w-10 h-10 border-2 border-black dark:border-white bg-pink-500 flex items-center justify-center">
587	              <span className="text-white text-lg">📷</span>
588	            </div>
589	          }
590	          defaultExpanded={instagramAssets.length > 0}
591	        />
592	        ) : null}
593	      </div>
594	        </>
595	      )}
596	    </div>
597	  );
598	}
